function Badge({
	className,
	variant,
	size,
	color,
	asChild = false,
	children,
	...props
}: BadgeProps) {
	const wrappedChildren = React.Children.map(children, (child) =>
		typeof child === "string" ? <span className="px-0.5">{child}</span> : child
	)

	if (asChild) {
		return (
			<Slot
				className={cn(badgeVariants({ variant, size, color }), className)}
				{...props}>
				{children}
			</Slot>
		)
	}
	return (
		<span
			className={cn(badgeVariants({ variant, size, color }), className)}
			{...props}>
			{wrappedChildren}
		</span>
	)
}
Badge.displayName = "Badge"

