export function useIsMobile(mobileBreakpoint = 768) {
	const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

	React.useEffect(() => {
		const mql = window.matchMedia(`(max-width: ${mobileBreakpoint - 1}px)`)
		const onChange = () => {
			setIsMobile(window.innerWidth < mobileBreakpoint)
		}
		mql.addEventListener("change", onChange)
		setIsMobile(window.innerWidth < mobileBreakpoint)
		return () => mql.removeEventListener("change", onChange)
	}, [mobileBreakpoint])

	return !!isMobile
}

function useSidebarResize({
	side = "left",
	minWidth,
	maxWidth,
	onWidthChange,
}: {
	side?: "left" | "right"
	minWidth: number
	maxWidth: number
	onWidthChange: (widthPx: number) => void
}) {
	const [isDragging, setIsDragging] = React.useState(false)
	const handleRef = React.useRef<HTMLDivElement>(null)

	React.useEffect(() => {
		const handle = handleRef.current
		if (!handle) return

		let startX = 0
		let startWidth = 0

		const onMouseMove = (e: MouseEvent) => {
			const delta = side === "left" ? e.clientX - startX : startX - e.clientX
			const next = Math.min(maxWidth, Math.max(minWidth, startWidth + delta))
			onWidthChange(next)
		}

		const onMouseUp = () => {
			setIsDragging(false)
			document.body.style.cursor = ""
			document.body.style.userSelect = ""
			window.removeEventListener("mousemove", onMouseMove)
			window.removeEventListener("mouseup", onMouseUp)
		}

		const onMouseDown = (e: MouseEvent) => {
			e.preventDefault()
			startX = e.clientX
			const sidebar = handle.closest<HTMLElement>(
				'[data-slot="sidebar-container"]'
			)
			startWidth = sidebar
				? sidebar.offsetWidth
				: parseFloat(SIDEBAR_WIDTH_DEFAULT) * 16
			setIsDragging(true)
			document.body.style.cursor = "col-resize"
			document.body.style.userSelect = "none"
			window.addEventListener("mousemove", onMouseMove)
			window.addEventListener("mouseup", onMouseUp)
		}

		const onTouchMove = (e: TouchEvent) => {
			const touch = e.touches[0]
			const delta =
				side === "left" ? touch.clientX - startX : startX - touch.clientX
			const next = Math.min(maxWidth, Math.max(minWidth, startWidth + delta))
			onWidthChange(next)
		}

		const onTouchEnd = () => {
			setIsDragging(false)
			window.removeEventListener("touchmove", onTouchMove)
			window.removeEventListener("touchend", onTouchEnd)
		}

		const onTouchStart = (e: TouchEvent) => {
			const touch = e.touches[0]
			startX = touch.clientX
			const sidebar = handle.closest<HTMLElement>(
				'[data-slot="sidebar-container"]'
			)
			startWidth = sidebar
				? sidebar.offsetWidth
				: parseFloat(SIDEBAR_WIDTH_DEFAULT) * 16
			setIsDragging(true)
			window.addEventListener("touchmove", onTouchMove, { passive: true })
			window.addEventListener("touchend", onTouchEnd)
		}

		handle.addEventListener("mousedown", onMouseDown)
		handle.addEventListener("touchstart", onTouchStart, { passive: true })

		return () => {
			handle.removeEventListener("mousedown", onMouseDown)
			handle.removeEventListener("touchstart", onTouchStart)
			window.removeEventListener("mousemove", onMouseMove)
			window.removeEventListener("mouseup", onMouseUp)
			window.removeEventListener("touchmove", onTouchMove)
			window.removeEventListener("touchend", onTouchEnd)
		}
	}, [side, minWidth, maxWidth, onWidthChange])

	return { handleRef, isDragging }
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
	const context = React.useContext(SidebarContext)
	if (!context) {
		throw new Error("useSidebar must be used within a SidebarProvider.")
	}
	return context
}

function SidebarProvider({
	defaultOpen = true,
	open: openProp,
	onOpenChange: setOpenProp,
	shortcut = "b",
	defaultWidth = SIDEBAR_WIDTH_DEFAULT,
	className,
	style,
	children,
	...props
}: SidebarProviderProps) {
	const isMobile = useIsMobile()
	const [openMobile, setOpenMobile] = React.useState(false)
	const [_open, _setOpen] = React.useState(defaultOpen)
	const open = openProp ?? _open

	const [sidebarWidth, _setSidebarWidth] = React.useState(defaultWidth)
	const [isResizing, setIsResizing] = React.useState(false)

	const setOpen = React.useCallback(
		(value: boolean | ((value: boolean) => boolean)) => {
			const openState = typeof value === "function" ? value(open) : value
			if (setOpenProp) {
				setOpenProp(openState)
			} else {
				_setOpen(openState)
			}
			document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
		},
		[setOpenProp, open]
	)

	const setSidebarWidth = React.useCallback((width: string) => {
		_setSidebarWidth(width)
	}, [])

	const toggleSidebar = React.useCallback(() => {
		return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open)
	}, [isMobile, setOpen, setOpenMobile])

	React.useEffect(() => {
		const handleKeyDown = (event: KeyboardEvent) => {
			const tag = (event.target as HTMLElement)?.tagName
			if (
				tag === "INPUT" ||
				tag === "TEXTAREA" ||
				(event.target as HTMLElement)?.isContentEditable
			)
				return
			if (event.key === shortcut && (event.metaKey || event.ctrlKey)) {
				event.preventDefault()
				toggleSidebar()
			}
		}
		window.addEventListener("keydown", handleKeyDown)
		return () => window.removeEventListener("keydown", handleKeyDown)
	}, [toggleSidebar, shortcut])

	const state = open ? "expanded" : "collapsed"

	const contextValue = React.useMemo<SidebarContextProps>(
		() => ({
			state,
			open,
			setOpen,
			isMobile,
			openMobile,
			setOpenMobile,
			toggleSidebar,
			sidebarWidth,
			setSidebarWidth,
			isResizing,
			setIsResizing,
		}),
		[
			state,
			open,
			setOpen,
			isMobile,
			openMobile,
			setOpenMobile,
			toggleSidebar,
			sidebarWidth,
			setSidebarWidth,
			isResizing,
			setIsResizing,
		]
	)

	return (
		<SidebarContext.Provider value={contextValue}>
			<Tooltip delayDuration={0}>
				<div
					data-slot="sidebar-wrapper"
					style={
						{
							"--sidebar-width": sidebarWidth,
							"--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
							...style,
						} as React.CSSProperties
					}
					className={cn(
						// Structural
						"group/sidebar-wrapper flex min-h-svh w-full",
						// Style hook
						"bg-bg has-data-[theme=default]:bg-bg has-data-[theme=gray]:has-data-[variant=inset]:bg-sidebar has-data-[theme=inverse]:has-data-[variant=inset]:bg-black",
						className
					)}
					{...props}>
					{children}
				</div>
			</Tooltip>
		</SidebarContext.Provider>
	)
}

const sidebarThemeVars: Record<
	NonNullable<SidebarProps["theme"]>,
	React.CSSProperties
> = {
	default: { "--color-sidebar": "var(--color-bg)" } as React.CSSProperties,
	gray: {
		"--color-sidebar": "var(--color-fill1)",
		"--color-sidebar-accent": "var(--color-fill2)",
	} as React.CSSProperties,
	"gray-body": { "--color-sidebar": "var(--color-bg)" } as React.CSSProperties,
	inverse: { "--color-sidebar": "var(--color-black)" } as React.CSSProperties,
}

function SidebarResizeHandle({
	className,
	side = "left",
	minWidth = parseFloat(SIDEBAR_WIDTH_MIN) * 16,
	maxWidth = parseFloat(SIDEBAR_WIDTH_MAX) * 16,
	...props
}: SidebarResizeHandleProps) {
	const { setSidebarWidth, setIsResizing } = useSidebar()

	const handleWidthChange = React.useCallback(
		(widthPx: number) => {
			setSidebarWidth(`${widthPx}px`)
		},
		[setSidebarWidth]
	)

	const { handleRef, isDragging } = useSidebarResize({
		side,
		minWidth,
		maxWidth,
		onWidthChange: handleWidthChange,
	})

	React.useEffect(() => {
		setIsResizing(isDragging)
	}, [isDragging, setIsResizing])

	return (
		<div
			ref={handleRef}
			data-slot="sidebar-resize-handle"
			data-sidebar="resize-handle"
			data-dragging={isDragging || undefined}
			aria-hidden="true"
			className={cn(
				// Structural
				"absolute inset-y-0 z-20 w-1.5 cursor-col-resize",
				side === "left" ? "-right-0.5" : "-left-0.5",
				"after:absolute after:inset-y-0 after:left-1/2 after:w-[2px] after:-translate-x-1/2 after:rounded-full",
				"after:transition-colors after:duration-150",
				// Style hooks
				"hover:after:bg-sidebar-border after:bg-transparent",
				isDragging && "after:bg-sidebar-ring",
				// Hide when icon-collapsed
				"group-data-[collapsible=icon]:hidden",
				className
			)}
			{...props}
		/>
	)
}

function Sidebar({
	side = "left",
	variant = "sidebar",
	collapsible = "offcanvas",
	theme = "default",
	resizable = false,
	minWidth = parseFloat(SIDEBAR_WIDTH_MIN) * 16,
	maxWidth = parseFloat(SIDEBAR_WIDTH_MAX) * 16,
	className,
	children,
	...props
}: SidebarProps) {
	const { isMobile, state, openMobile, setOpenMobile, isResizing } =
		useSidebar()

	if (collapsible === "none") {
		return (
			<div
				data-slot="sidebar"
				data-theme={theme}
				style={sidebarThemeVars[theme]}
				className={cn(
					// Structural
					"w-(--sidebar-width) sticky top-0 flex h-svh flex-col",
					// Style hook
					"bg-sidebar text-sidebar-fg",
					theme === "inverse" && "dark",
					className
				)}
				{...props}>
				{children}
			</div>
		)
	}

	if (isMobile) {
		return (
			<Drawer
				open={openMobile}
				onOpenChange={setOpenMobile}
				direction={side}
				handle={false}>
				<DrawerContent
					data-sidebar="sidebar"
					data-slot="sidebar"
					data-mobile="true"
					className={cn(
						// Structural
						"w-(--sidebar-width) group p-0",
						// Style hook
						"bg-sidebar text-sidebar-fg",
						theme === "inverse" && "dark",
						className
					)}
					style={
						{
							"--sidebar-width": SIDEBAR_WIDTH_MOBILE,
							...sidebarThemeVars[theme],
						} as React.CSSProperties
					}>
					<DialogTitle className="hidden" />
					<div className="flex h-full w-full flex-col">{children}</div>
				</DrawerContent>
			</Drawer>
		)
	}

	return (
		<div
			style={sidebarThemeVars[theme]}
			className={cn(
				"text-sidebar-fg group peer hidden md:block",
				theme === "inverse" && "dark"
			)}
			data-state={state}
			data-collapsible={state === "collapsed" ? collapsible : ""}
			data-variant={variant}
			data-theme={theme}
			data-side={side}
			data-slot="sidebar">
			{/* Gap element — keeps layout space while sidebar is fixed-positioned */}
			<div
				data-slot="sidebar-gap"
				className={cn(
					// Structural
					"w-(--sidebar-width) relative bg-transparent",
					!isResizing && "transition-[width] duration-200 ease-linear",
					"group-data-[collapsible=offcanvas]:w-0",
					"group-data-[side=right]:rotate-180",
					variant === "floating"
						? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(6))+2px)]"
						: "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
				)}
			/>

			{/* Fixed container */}
			<div
				data-slot="sidebar-container"
				className={cn(
					"w-(--sidebar-width) fixed inset-y-0 z-10 hidden h-svh md:flex",
					!isResizing &&
						"transition-[left,right,width] duration-200 ease-linear",
					side === "left"
						? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
						: "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
					variant === "inset"
						? "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
						: variant === "floating"
							? "p-3 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(6))+2px)]"
							: "group-data-[collapsible=icon]:w-(--sidebar-width-icon)",
					variant === "sidebar" &&
						"border-sidebar-border group-data-[side=left]:border-r group-data-[side=right]:border-l",
					variant === "floating" && "",
					variant === "inset" && "",
					"group-data-[theme=gray-body]:group-data-[variant=floating]:bg-fill1",
					className
				)}
				{...props}>
				<div
					data-sidebar="sidebar"
					data-slot="sidebar-inner"
					className={cn(
						"bg-sidebar relative flex h-full w-full flex-col",
						variant === "floating" &&
							"border-sidebar-border rounded-xl border shadow-sm",
						variant === "inset" && "rounded-lg"
					)}>
					{children}

					{resizable && (
						<SidebarResizeHandle
							side={side}
							minWidth={minWidth}
							maxWidth={maxWidth}
						/>
					)}
				</div>
			</div>
		</div>
	)
}

